package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxRec TaxRec
var taxFileLines []string
var taxFileIdx int

func formatEdited(val decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	var intPic string
	var fracPic string
	scale := 0
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
		scale = len(fracPic)
	} else {
		intPic = picture
		fracPic = ""
		scale = 0
	}
	// digit capacity for integer part
	intCap := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intCap++
		}
	}
	// get string representation with required scale
	// Use StringFixed to get rounding/truncation to scale (value already fits)
	var s string
	if scale > 0 {
		s = val.StringFixed(int32(scale))
	} else {
		s = val.StringFixed(0)
	}
	// handle sign not needed (positive)
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	var intStr string
	var fracStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
			// ensure length scale
			if len(fracStr) < scale {
				fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
			} else if len(fracStr) > scale {
				fracStr = fracStr[:scale]
			}
		} else {
			fracStr = strings.Repeat("0", scale)
		}
	} else {
		intStr = s
		fracStr = ""
	}
	if intStr == "" {
		intStr = "0"
	}
	// high-order truncation
	if len(intStr) > intCap {
		intStr = intStr[len(intStr)-intCap:]
	}
	// pad with leading zeros to intCap
	if len(intStr) < intCap {
		intStr = strings.Repeat("0", intCap-len(intStr)) + intStr
	}
	// Now map digits to intPic
	digits := []rune(intStr) // length intCap
	resInt := make([]rune, len(intPic))
	di := 0
	suppressed := true
	for i, ch := range intPic {
		switch ch {
		case 'Z', '9':
			d := digits[di]
			di++
			if suppressed {
				if ch == 'Z' && d == '0' {
					resInt[i] = ' '
				} else {
					suppressed = false
					resInt[i] = d
				}
			} else {
				resInt[i] = d
			}
		case ',':
			if suppressed {
				resInt[i] = ' '
			} else {
				resInt[i] = ','
			}
		case '.':
			resInt[i] = '.'
		default:
			resInt[i] = ch
		}
	}
	if scale > 0 {
		// fractional part is always digits (9s)
		// res = string(resInt) + "." + fracStr
		return string(resInt) + "." + fracStr
	}
	return string(resInt)
}

func formatCount(v int64, digits int) string {
	// low-order digits only, zero padded
	s := fmt.Sprintf("%d", v)
	if s[0] == '-' {
		s = s[1:]
	}
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func readTaxFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		taxFileLines = []string{}
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 10*1024*1024)
	for sc.Scan() {
		line := sc.Text()
		// Scanner strips newline, keeps content without newline
		// Keep as is (may contain trailing spaces trimmed by scanner? Scanner keeps them)
		// Actually bufio.Scanner splits on \n and removes it but preserves other chars.
		taxFileLines = append(taxFileLines, line)
	}
	taxFileIdx = 0
}

func MAIN_PARA() {
	// OPEN INPUT TAX-FILE
	readTaxFile()
	READ_PARA()
	for !(WsEofFlag == "Y") {
		PROCESS_PARA()
	}
	// CLOSE TAX-FILE (no-op)
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	countStr := formatCount(WsCount, 3)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func READ_PARA() {
	if taxFileIdx >= len(taxFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := taxFileLines[taxFileIdx]
	taxFileIdx++
	// pad with spaces to record length 13
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	// parse
	trId := line[0:5]
	rawIncome := line[5:13]
	trimmed := strings.TrimSpace(rawIncome)
	var inc decimal.Decimal
	if trimmed == "" {
		inc = decimal.NewFromInt(0)
	} else {
		// raw should be digits, maybe with spaces
		// Keep only digits? But spec says digits only
		// Use trimmed
		// Parse as integer
		var n int64 = 0
		// trimmed may still contain spaces inside? remove spaces
		t2 := strings.ReplaceAll(trimmed, " ", "")
		if t2 != "" {
			// parse decimal digits
			// use decimal directly to avoid overflow? length 8 fits int64
			fmt.Sscanf(t2, "%d", &n)
			inc = decimal.New(n, -2)
		} else {
			inc = decimal.NewFromInt(0)
		}
	}
	taxRec.TrId = trId
	taxRec.TrIncome = inc
}

func PROCESS_PARA() {
	// IF TR-INCOME <= 10000.00 ...
	hundred00 := decimal.NewFromInt(10000)
	// TR-INCOME scale 2, compare with 10000.00
	limit1 := decimal.New(1000000, -2) // 10000.00
	limit2 := decimal.New(4000000, -2) // 40000.00
	if taxRec.TrIncome.Cmp(limit1) <= 0 {
		// WS-TAX ROUNDED = TR-INCOME * 0.10
		// 0.10 = 1/10
		// compute with decimal
		rate := decimal.New(10, -2) // 0.10
		v := taxRec.TrIncome.Mul(rate)
		// Round to 2
		v = v.Round(2)
		// store with truncation to 2 handled by Round already; also low-order truncation
		// high-order truncation would be handled if > PIC 9(7)V99, but ignore
		WsTax = v
	} else {
		if taxRec.TrIncome.Cmp(limit2) <= 0 {
			// 1000.00 + (TR-INCOME -10000.00)*0.20
			diff := taxRec.TrIncome.Sub(limit1)
			rate := decimal.New(20, -2) // 0.20
			v := diff.Mul(rate)
			v = v.Add(decimal.New(100000, -2)) // 1000.00
			v = v.Round(2)
			WsTax = v
		} else {
			diff := taxRec.TrIncome.Sub(limit2)
			rate := decimal.New(30, -2) // 0.30
			v := diff.Mul(rate)
			v = v.Add(decimal.New(700000, -2)) // 7000.00
			v = v.Round(2)
			WsTax = v
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (no ROUNDED => truncate)
	// TR-INCOME and WS-TAX scale 2 so exact
	WsNet = taxRec.TrIncome.Sub(WsTax).Truncate(2)
	// ADD WS-TAX TO WS-TOTAL-TAX
	WsTotalTax = WsTotalTax.Add(WsTax)
	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	// MOVE to edited
	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	READ_PARA()
	_ = hundred00
}

func main() {
	MAIN_PARA()
}
